import{_ as n,a as t,o as a,a6 as r}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"List Shipments (Datagrid)","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-shipments-list-gql","title":"List Shipments (Datagrid)","description":"Cursor-paginated shipments datagrid. Every shipment column plus the order/customer context and both addresses is populated on each row — only the shipped line items are detail-only.","query":"query AdminShipments($first: Int, $after: String, $order_id: String) {\\n  adminShipments(first: $first, after: $after, order_id: $order_id) {\\n    edges {\\n      cursor\\n      node {\\n        id\\n        _id\\n        orderId\\n        orderIncrementId\\n        shippedTo\\n        orderDate\\n        orderStatus\\n        orderStatusLabel\\n        channelName\\n        customerName\\n        customerEmail\\n        status\\n        totalQty\\n        totalWeight\\n        carrierCode\\n        carrierTitle\\n        trackNumber\\n        emailSent\\n        inventorySourceId\\n        inventorySourceName\\n        billingAddress\\n        shippingAddress\\n        createdAt\\n        updatedAt\\n        items\\n      }\\n    }\\n    pageInfo {\\n      hasNextPage\\n      endCursor\\n    }\\n    totalCount\\n  }\\n}\\n","variables":"{\\n  \\"first\\": 10,\\n  \\"order_id\\": \\"8\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"adminShipments\\": {\\n      \\"edges\\": [\\n        {\\n          \\"cursor\\": \\"MA==\\",\\n          \\"node\\": {\\n            \\"id\\": \\"/api/admin/shipments/7\\",\\n            \\"_id\\": 7,\\n            \\"orderId\\": 8,\\n            \\"orderIncrementId\\": \\"8\\",\\n            \\"shippedTo\\": \\"John Doe\\",\\n            \\"orderDate\\": \\"2026-05-20 10:00:00\\",\\n            \\"orderStatus\\": \\"processing\\",\\n            \\"orderStatusLabel\\": \\"Processing\\",\\n            \\"channelName\\": \\"Default\\",\\n            \\"customerName\\": \\"John Doe\\",\\n            \\"customerEmail\\": \\"john.doe@example.com\\",\\n            \\"status\\": null,\\n            \\"totalQty\\": 2,\\n            \\"totalWeight\\": null,\\n            \\"carrierCode\\": null,\\n            \\"carrierTitle\\": \\"UPS\\",\\n            \\"trackNumber\\": \\"1Z999AA1\\",\\n            \\"emailSent\\": false,\\n            \\"inventorySourceId\\": 1,\\n            \\"inventorySourceName\\": \\"Default\\",\\n            \\"billingAddress\\": {\\n              \\"id\\": 16,\\n              \\"addressType\\": \\"order_billing\\",\\n              \\"firstName\\": \\"John\\",\\n              \\"lastName\\": \\"Doe\\",\\n              \\"city\\": \\"Los Angeles\\",\\n              \\"country\\": \\"US\\",\\n              \\"postcode\\": \\"90001\\",\\n              \\"email\\": \\"john.doe@example.com\\",\\n              \\"phone\\": \\"5551234567\\"\\n            },\\n            \\"shippingAddress\\": {\\n              \\"id\\": 15,\\n              \\"addressType\\": \\"order_shipping\\",\\n              \\"firstName\\": \\"John\\",\\n              \\"lastName\\": \\"Doe\\",\\n              \\"city\\": \\"Los Angeles\\",\\n              \\"country\\": \\"US\\",\\n              \\"postcode\\": \\"90001\\",\\n              \\"email\\": \\"john.doe@example.com\\",\\n              \\"phone\\": \\"5551234567\\"\\n            },\\n            \\"createdAt\\": \\"2026-05-20 12:00:00\\",\\n            \\"updatedAt\\": \\"2026-05-20 12:00:00\\",\\n            \\"items\\": []\\n          }\\n        }\\n      ],\\n      \\"pageInfo\\": {\\n        \\"hasNextPage\\": false,\\n        \\"endCursor\\": \\"MA==\\"\\n      },\\n      \\"totalCount\\": 1\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/sales/shipments/list.md","filePath":"api/graphql-api/admin/sales/shipments/list.md","lastUpdated":1787725411000}'),i={name:"api/graphql-api/admin/sales/shipments/list.md"};function s(o,e,d,l,h,p){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="list-shipments-datagrid" tabindex="-1">List Shipments (Datagrid) <a class="header-anchor" href="#list-shipments-datagrid" aria-label="Permalink to &quot;List Shipments (Datagrid)&quot;">​</a></h1><p>GraphQL counterpart of <code>GET /api/admin/shipments</code>. Returns a cursor-paginated list of shipments — the same rows shown on the admin <strong>Sales → Shipments</strong> datagrid. Every shipment <strong>column</strong> plus the order/customer context and both the billing and shipping addresses are populated on each row, so the field set is identical to <a href="/api/graphql-api/admin/sales/orders/get-shipment.html">Shipment Detail</a> except for the shipped line <code>items</code>, which are returned only by the detail query (<code>[]</code> on the listing).</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><p><code>adminShipments(first, after, id, order_id, total_qty, inventory_source_name, shipped_to, order_date_from, order_date_to, created_at_from, created_at_to, sort, order)</code> — a cursor <code>QueryCollection</code>. Every REST query parameter is also exposed as a GraphQL argument; see the <a href="/api/rest-api/admin/sales/shipments/list.html">REST page</a> for the full argument table.</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.shipments.view</code></p><h3 id="nested-objects-are-returned-whole" tabindex="-1">Nested Objects Are Returned Whole <a class="header-anchor" href="#nested-objects-are-returned-whole" aria-label="Permalink to &quot;Nested Objects Are Returned Whole&quot;">​</a></h3><p><code>billingAddress</code>, <code>shippingAddress</code> and <code>items</code> are returned as JSON — <strong>query them bare, without a sub-selection</strong> (<code>shippingAddress</code>, not <code>shippingAddress { … }</code>). The whole object/array comes back. See <a href="/api/graphql-api/admin/sales/orders/get-shipment.html">Shipment Detail</a> for the keys inside each.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>Every field is populated on each row — the shipment columns, the order/customer context, and both address objects. Only the shipped line <code>items</code> are left empty (<code>[]</code>) on the listing. The full per-field reference is on the <a href="/api/graphql-api/admin/sales/orders/get-shipment.html">Shipment Detail</a> page.</p><h2 id="listing-vs-fetching-one" tabindex="-1">Listing vs. fetching one <a class="header-anchor" href="#listing-vs-fetching-one" aria-label="Permalink to &quot;Listing vs. fetching one&quot;">​</a></h2><p>The listing already carries the full payload — fetching a single shipment by id (<code>adminShipment(id:)</code>) is only needed when you want the shipped line <code>items</code>, or when you already hold a shipment id and want just that record. Typical flow: list with <code>adminShipments</code>, read <code>_id</code> from the row you want, then fetch the full record.</p>',12)]))}const u=n(i,[["render",s]]);export{m as __pageData,u as default};
